	@Test
	void headRequestsDoNotOpenRepositoryConnectionsOrWriteRows() throws Exception {
		for (AbstractController controller : List.of(new NamespacesController(), new ContextsController())) {
			MockHttpServletRequest request = new MockHttpServletRequest("HEAD", "/repositories/test/metadata");
			request.addHeader("Accept", "application/sparql-results+json");
			MockHttpServletResponse response = new MockHttpServletResponse();
			Repository repository = mock(Repository.class);
			request.setAttribute("repository", repository);

			ModelAndView modelAndView = controller.handleRequest(request, response);
			modelAndView.getView().render(modelAndView.getModel(), request, response);

			assertThat(response.getStatus()).isEqualTo(200);
			assertThat(response.getContentAsByteArray()).isEmpty();
			verifyNoInteractions(repository);
		}
	}

	@Test
	void namespacesCloseConnectionAfterRenderingAndOnIterationError() throws Exception {
		MockHttpServletRequest request = new MockHttpServletRequest("GET", "/repositories/test/namespaces");
		request.addHeader("Accept", "application/sparql-results+json");
		MockHttpServletResponse response = new MockHttpServletResponse();
		Repository repository = mock(Repository.class);
		RepositoryConnection connection = mock(RepositoryConnection.class);
		request.setAttribute("repository", repository);
		when(repository.getConnection()).thenReturn(connection);
		when(connection.getParserConfig()).thenReturn(new ParserConfig());
		when(connection.getValueFactory()).thenReturn(SimpleValueFactory.getInstance());
		@SuppressWarnings("unchecked")
		RepositoryResult<Namespace> namespaces = mock(RepositoryResult.class);
		when(namespaces.hasNext()).thenReturn(true).thenThrow(new RepositoryException("namespace iteration failed"));
		when(namespaces.next()).thenReturn(new SimpleNamespace("first-prefix", "urn:first:"));
		when(connection.getNamespaces()).thenReturn(namespaces);

		ModelAndView modelAndView = new NamespacesController().handleRequest(request, response);
		verify(connection, never()).close();
		assertThatThrownBy(() -> modelAndView.getView().render(modelAndView.getModel(), request, response))
				.isInstanceOf(RepositoryException.class)
				.hasMessageContaining("namespace iteration failed");
		verify(namespaces).close();
		verify(connection).close();
	}

